def forward(groups):
    octets = groups[0].split('.')
    packed = 0
    for i, octet in enumerate(octets):
        packed |= int(octet) << (8 * (3 - i))
    return {'stored': [packed], 'layout': []}

def inverse(record):
    packed = record['stored'][0]
    octets = [(packed >> (8 * i)) & 0xFF for i in range(3, -1, -1)]
    return '.'.join(map(str, octets))
